import {AudioRouting,AudioMixerGraph,createAudioMixer} from '../audio-mixer.js';import {BufferedAudioPlayer} from '../buffered-audio.js';import {mixerVoiceGains} from '../mixer-voice-audibility.js';
const assert=(v,m)=>{if(!v)throw Error(m);},close=(a,b,e=.0001)=>assert(Math.abs(a-b)<e,`${a} != ${b}`);
async function scenario({muted=false,send=false,mode='mixer'}={}){
 const context=new OfflineAudioContext(1,4800,48000),data=createAudioMixer('OwnedVoice');data.buses.find(b=>b.id==='music').mute=muted;if(send)data.buses.find(b=>b.id==='music').sends=[{bus:'sfx',level:0,preFader:true}];const routing=new AudioRouting({context,readAsset:async()=>data}),buffer=context.createBuffer(1,4800,48000);const samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=.25*Math.sin(2*Math.PI*1000*i/48000);const a=new BufferedAudioPlayer(context,buffer),b=new BufferedAudioPlayer(context,buffer);a.setVirtual(true);b.setVirtual(true);await a.play();await b.play();await routing.connect(a,{mixer:'Assets/Owned.hbmixer.json',bus:'music',volume:1,priority:128});await routing.connect(b,{volume:.5,priority:128});routing.setVoiceBudget(1,2,mode);const selectedA=routing.voices.get(a).real,selectedB=routing.voices.get(b).real,stats=routing.voiceStats(),graph=routing.graphs.values().next().value;const gain=graph.voiceGains().get('music');const result=await context.startRendering(),pcm=result.getChannelData(0);let power=0;for(const v of pcm)power+=v*v;const rms=Math.sqrt(power/pcm.length);routing.dispose();
 // Preserve the existing filter/compressor start-up response. Build an independent full graph
 // for just the selected source; every PCM sample must match the production routing result.
 const referenceContext=new OfflineAudioContext(1,4800,48000),referenceGraph=new AudioMixerGraph(referenceContext,data),referenceBuffer=referenceContext.createBuffer(1,4800,48000);referenceBuffer.getChannelData(0).set(samples);const source=referenceContext.createBufferSource();source.buffer=referenceBuffer;const input=referenceContext.createGain();input.gain.value=selectedA?1:.5;source.connect(input);input.connect(selectedA?referenceGraph.input('music'):referenceContext.destination);source.start();const reference=(await referenceContext.startRendering()).getChannelData(0);let maximumError=0,referencePower=0;for(let i=0;i<pcm.length;i++){maximumError=Math.max(maximumError,Math.abs(pcm[i]-reference[i]));referencePower+=reference[i]*reference[i];}assert(maximumError<.000001,'routing PCM differs from selected-source graph: '+maximumError);referenceGraph.dispose();return {mode,muted,send,selectedA,selectedB,gain,rms,referenceRMS:Math.sqrt(referencePower/reference.length),maximumError,stats};
}
export async function runAudioAudibility(){const ordinary=await scenario(),muted=await scenario({muted:true}),legacy=await scenario({muted:true,mode:'legacy'}),preSend=await scenario({muted:true,send:true});assert(ordinary.selectedA&&!ordinary.selectedB,'ordinary larger source');assert(!muted.selectedA&&muted.selectedB&&muted.gain===0,'muted mixer releases budget');assert(legacy.selectedA&&!legacy.selectedB,'legacy policy');assert(preSend.selectedA&&!preSend.selectedB&&preSend.gain===1,'pre-fader send remains audible');close(ordinary.rms,ordinary.referenceRMS,.000001);close(muted.rms,.125/Math.sqrt(2),.01);close(legacy.rms,0,.000001);close(preSend.rms,preSend.referenceRMS,.000001);assert(muted.stats.mixerSilentActive===1,'silent diagnostics');
 // A real DynamicsCompressor reduction updates the routing estimate without reading PCM per voice.
 const context=new OfflineAudioContext(1,48000,48000),data=createAudioMixer('OwnedCompressor');const bus=data.buses.find(b=>b.id==='music');Object.assign(bus,{compressor:true,threshold:-40,ratio:20,attack:.001,release:.5});const graph=new AudioMixerGraph(context,data),source=context.createOscillator();source.frequency.value=1000;source.connect(graph.input('music'));source.start();const stopped=context.suspend(.5),render=context.startRendering();await stopped;const reduction=graph.nodes.get('music').compressor.reduction,estimated=graph.voiceGains().get('music');const masterReduction=graph.nodes.get('master').compressor.reduction;assert(reduction< -5,'actual compressor reduction');close(estimated,10**((reduction+masterReduction)/20));await context.resume();await render;graph.dispose();
 return {passed:true,actualOfflineAudio:true,scenarios:[ordinary,muted,legacy,preSend],compressor:{reduction,masterReduction,estimated},GUI:false};
}
